def main():
    hits = repo.search("compatibility|VERSION|legacy", glob="**")
    out = []
    for h in hits:
        out.append("%s:%d: %s" % (h.path, h.line, h.text.strip()))
    allfiles = repo.search("fn ", glob="**")
    files = []
    for h in allfiles:
        if h.path not in files:
            files.append(h.path)
    return {"hits": out[:40], "rs_files": files}

result = main()
return result
